import math
from qiskit import QuantumCircuit

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    a = [6, 5, 12, 6, 6]

    # Compute the sum: for each problem qubit, add its weight to the ancilla register
    for i in range(5):
        c = problem_qubits[i]
        w = a[i]
        for j in range(6):
            if w & (1 << j):
                for k in range(j, 5):
                    qc.ccx(c, ancilla_qubits[k], ancilla_qubits[k+1])
                qc.cx(c, ancilla_qubits[j])

    # Flip ancilla qubits that are 0 in the target state 24 (binary 011000) to 1
    # Positions (LSB to MSB): 0,1,2,3,4,5 -> 24 is 0b011000, so bits 0,1,2,5 are 0 -> flip these
    for j in [0, 1, 2, 5]:
        qc.x(ancilla_qubits[j])

    # Apply multi-controlled phase gate (equivalent to Z) with angle pi when ancilla is all 1s (after flip)
    qc.mcp(math.pi, ancilla_qubits, problem_qubits[0])

    # Flip back the ancilla qubits
    for j in [0, 1, 2, 5]:
        qc.x(ancilla_qubits[j])

    # Uncompute the sum by reversing the computation steps
    for i in range(4, -1, -1):
        c = problem_qubits[i]
        w = a[i]
        for j in range(5, -1, -1):
            if w & (1 << j):
                qc.cx(c, ancilla_qubits[j])
                for k in range(4, j-1, -1):
                    qc.ccx(c, ancilla_qubits[k], ancilla_qubits[k+1])
